WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_esc_basic'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '扶梯基础', 'kp-trv-esc-basic', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "扶梯基础"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "扶梯也是一种流水行船。扶梯级数 = 人走级数 + 电梯走的级数。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“商场里有一部向上运行的自动扶梯，小明顺着扶梯往上走，走了 30 级到达顶部……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "扶梯的“级数”等价于路程 S。"}]}, {"type": "katexBlock", "attrs": {"content": "S_{总级数} = (V_{人} \\pm V_{梯}) \\times T = N_{人} \\pm N_{梯}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目判定人是顺着电梯走还是逆着走] --> B{运动方向?}\nB -- 顺向(同向) --> C[总级数 = 人自己走的级数 + 电梯偷偷送上去的级数]\nB -- 逆向(反向) --> D[总级数 = 人自己跑的级数 - 电梯偷偷送回去的级数]\nC --> E[提取各自的级数或速度进行代数计算]\nD --> E"}}]}$$ AS jsonb), NULL, '扶梯基础的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "扶梯基础"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_esc_basic", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
